export interface SystemPromptOptions {
  maxTokens?: number;          // default: 4000
  includeCompliance?: boolean; // default: true si hay complianceReport
  language?: 'en' | 'es';     // default: 'en'
  sections?: SystemPromptSection[];  // orden y selección de secciones
}

export type SystemPromptSection =
  | 'role'
  | 'project-context'
  | 'tech-stack'
  | 'conventions'
  | 'compliance'
  | 'constraints';

async toSystemPrompt(options: SystemPromptOptions = {}): Promise<string> {
  const output = await this.collectContext();
  const agent = this.agent;
  const language = options.language ?? 'en';
  const sections: string[] = [];

  // Sección ROLE
  if (agent) {
    sections.push(buildRoleSection(agent, language));
  }

  // Sección PROJECT CONTEXT (de PackageJsonAdapter o GenericFsAdapter)
  const pkgCtx = output.contexts.find(c => c.type === 'package-json');
  const gitCtx = output.contexts.find(c => c.type === 'git');
  if (pkgCtx || gitCtx) {
    sections.push(buildProjectSection(pkgCtx, gitCtx, language));
  }

  // Sección TECH STACK
  if (pkgCtx?.data?.stack) {
    sections.push(buildStackSection(pkgCtx.data.stack as any, language));
  }

  // Sección COMPLIANCE (de complianceReport si existe)
  if (options.includeCompliance !== false && output.complianceReport) {
    sections.push(buildComplianceSection(output.complianceReport, language));
  }

  const prompt = sections.join('\n\n---\n\n');

  // Truncar si supera maxTokens
  const maxChars = (options.maxTokens ?? 4000) * 4;
  return prompt.length > maxChars ? prompt.slice(0, maxChars) + '\n[context truncated]' : prompt;
}

